mapper.select:
SELECT
 id, parentId, typeId, completed, name, description
FROM tasks WHERE id=#{value}

SELECT
 id, parentId, typeId, completed, name, description
FROM tasks WHERE parentId=#{value}


SELECT lineId, start, stop
FROM timelines WHERE start <= #{value}
ORDER BY start DESC LIMIT 1

