UPDATE timeslice
SET taskId = #{taskId}, type = #{typeId}, note = #{note}, duration = #{duration}
WHERE lineId = #{timelineId} AND start = #{start}

UPDATE TASKS SET typeId=#{typeId}, completed=#{isCompleted},
name=#{name}, description=#{description}
WHERE id=#{id}
